tool_input.code:
s='[C][N][C][=C][C][C][Ring1][Branch1][=O]'
print('Input:',s)
try:
 import selfies
 print('SELFIES decode:', selfies.decoder(s))
except Exception as e: print('SELFIES decoding unavailable/failed:',type(e).__name__,str(e))
try:
 from rdkit import Chem
 m=Chem.MolFromSmiles(s)
 print('RDKit SMILES parse:', 'success' if m else 'failed')
 if m: print(Chem.MolToSmiles(m))
except Exception as e: print('RDKit unavailable/failed:',type(e).__name__,str(e))

for x in ['pyscf','psi4','rdkit']:
 try:
  m=__import__(x); print(x,'available',getattr(m,'__version__',''))
 except Exception as e: print(x,'unavailable',type(e).__name__)
